mapper.select:
select s.*, c.name as clazzName from student as s left join clazz c on s.clazz_id = c.id
and s.name like concat('%', #{name}, '%')
and s.degree = #{degree}
and s.clazz_id = #{clazzId}
order by s.update_time desc

select id, name, no, gender, phone, id_card as idCard, is_college as isCollege, address, degree, graduation_date, clazz_id as clazzId, violation_count as violationCount, violation_score as violationScore, create_time as createTime, update_time as updateTime
from student
where id = #{id}

mapper.update:
update student
name = #{name}, no = #{no}, gender = #{gender}, phone = #{phone}, id_card = #{idCard}, is_college = #{isCollege}, address = #{address}, degree = #{degree}, graduation_date = #{graduationDate}, clazz_id = #{clazzId}, update_time = NOW(),
where id = #{id}
